tests["verne15"] = r"""(function(){const errors=[];try{openStory('around-the-world-in-eighty-days-towle');stlChapter(14)}catch(e){errors.push('navigation: '+e.message)}const reader=document.querySelector('.reader');if(state.page!=='reader')errors.push('page='+state.page);if(state.chapter!==14)errors.push('chapter='+state.chapter);if(state.story?.id!=='around-the-world-in-eighty-days-towle')errors.push('story='+state.story?.id);if(!reader)errors.push('reader missing');if(reader&&!reader.textContent.includes('Judge Obadiah'))errors.push('judge text missing');if(reader&&!reader.textContent.includes('15 of 37'))errors.push('full novel progress missing');if(reader&&!reader.textContent.includes('نهاية الفصل 15'))errors.push('chapter-end label missing; current='+state.chapter+'; available='+state.story?.chapters?.length+'; total='+state.story?.totalChapters+'; end='+reader.querySelector('.chapter-end div')?.textContent);if(reader&&reader.textContent.includes('The End'))errors.push('false ending label present');document.body.setAttribute('data-storylens-qa',errors.length?'FAIL':'PASS');document.body.setAttribute('data-storylens-qa-errors',errors.join(' | '));document.body.setAttribute('data-stl-screenshot','verne15')})();"""
