tests["verne21"] = r"""(function(){const errors=[];try{openStory('around-the-world-in-eighty-days-towle');stlChapter(20)}catch(e){errors.push('navigation: '+e.message)}const reader=document.querySelector('.reader');if(state.page!=='reader')errors.push('page='+state.page);if(state.chapter!==20)errors.push('chapter='+state.chapter);if(!reader||!reader.textContent.includes('Shanghai'))errors.push('Chapter XXI Shanghai passage missing');if(!reader||!reader.textContent.includes('21 of 37'))errors.push('novel progress missing');if(reader&&reader.textContent.includes('يتبع — لم تكتمل الرواية بعد'))errors.push('Chapter XXI incorrectly treated as last available');const primary=reader?.querySelector('.chapter-end > button.primary');if(reader&&(!primary||!String(primary.getAttribute('onclick')).includes('nextChapter')))errors.push('Arabic next-chapter action missing');const navNext=reader?.querySelectorAll('.lt-chapter-nav button')[1];if(reader&&(!navNext||navNext.disabled))errors.push('Chapter XXII navigation should be enabled');if(reader&&reader.textContent.includes('The End'))errors.push('false ending label present');document.body.setAttribute('data-storylens-qa',errors.length?'FAIL':'PASS');document.body.setAttribute('data-storylens-qa-errors',errors.join(' | '));document.body.setAttribute('data-stl-screenshot','verne21')})();"""
tests["verne21-en"] = r"""(function(){document.documentElement.lang='en';document.documentElement.dir='ltr';const errors=[];try{openStory('around-the-world-in-eighty-days-towle');stlChapter(20)}catch(e){errors.push('navigation: '+e.message)}const reader=document.querySelector('.reader');const end=reader?.querySelector('.chapter-end > div');const button=reader?.querySelector('.chapter-end > button.primary');if(state.page!=='reader')errors.push('page='+state.page);if(state.chapter!==20)errors.push('chapter='+state.chapter);if(!reader||!reader.textContent.includes('21 of 37'))errors.push('novel progress missing');if(!reader||!reader.textContent.includes('Shanghai'))errors.push('Chapter XXI source passage missing');if(end&&(end.textContent.trim()==='To be continued — more chapters are coming'||end.textContent.trim()==='The End'))errors.push('Chapter XXI should remain a normal chapter: '+end.textContent);if(!button||!String(button.getAttribute('onclick')).includes('nextChapter'))errors.push('English next-chapter action missing');const nav=reader?.querySelectorAll('.lt-chapter-nav button');if(!nav||nav.length<2||nav[0].textContent.trim()!=='← Previous chapter'||nav[1].textContent.trim()!=='Next chapter →'||nav[1].disabled)errors.push('English chapter navigation labels/state incorrect');document.body.setAttribute('data-storylens-qa',errors.length?'FAIL':'PASS');document.body.setAttribute('data-storylens-qa-errors',errors.join(' | '));document.body.setAttribute('data-stl-screenshot','verne21-en')})();"""
tests["verne22"] = r"""(function(){const errors=[];try{openStory('around-the-world-in-eighty-days-towle');stlChapter(21)}catch(e){errors.push('navigation: '+e.message)}const reader=document.querySelector('.reader');if(state.page!=='reader')errors.push('page='+state.page);if(state.chapter!==21)errors.push('chapter='+state.chapter);if(!reader||!reader.textContent.includes('Yokohama'))errors.push('Chapter XXII Yokohama passage missing');if(!reader||!reader.textContent.includes('23 من 37'))errors.push('available chapter count missing');const navNext=reader?.querySelectorAll('.lt-chapter-nav button')[1];if(reader&&(!navNext||navNext.disabled))errors.push('Chapter XXIII must be available from Chapter XXII');if(reader&&reader.textContent.includes('يتبع — لم تكتمل الرواية بعد'))errors.push('premature terminal label present');if(reader&&reader.textContent.includes('The End'))errors.push('false ending label present');document.body.setAttribute('data-storylens-qa',errors.length?'FAIL':'PASS');document.body.setAttribute('data-storylens-qa-errors',errors.join(' | '));document.body.setAttribute('data-stl-screenshot','verne22')})();""";
tests["verne22-en"] = r"""(function(){document.documentElement.lang='en';document.documentElement.dir='ltr';const errors=[];try{openStory('around-the-world-in-eighty-days-towle');stlChapter(21)}catch(e){errors.push('navigation: '+e.message)}const reader=document.querySelector('.reader');if(state.page!=='reader')errors.push('page='+state.page);if(state.chapter!==21)errors.push('chapter='+state.chapter);if(!reader||!reader.textContent.includes('23 of 37'))errors.push('available chapter count missing');if(!reader||!reader.textContent.includes('Yokohama'))errors.push('Chapter XXII source passage missing');const nav=reader?.querySelectorAll('.lt-chapter-nav button');if(!nav||nav.length<2||nav[1].disabled||nav[1].textContent.trim()!=='Next chapter →')errors.push('English next-chapter state incorrect');if(reader&&reader.textContent.includes('To be continued — more chapters are coming'))errors.push('premature terminal label present');document.body.setAttribute('data-storylens-qa',errors.length?'FAIL':'PASS');document.body.setAttribute('data-storylens-qa-errors',errors.join(' | '));document.body.setAttribute('data-stl-screenshot','verne22-en')})();""";
tests["verne23"] = r"""(function(){const errors=[];try{openStory('around-the-world-in-eighty-days-towle');stlChapter(22)}catch(e){errors.push('navigation: '+e.message)}const reader=document.querySelector('.reader');const end=reader?.querySelector('.chapter-end > div');const primary=reader?.querySelector('.chapter-end > button.primary');if(state.page!=='reader')errors.push('page='+state.page);if(state.chapter!==22)errors.push('chapter='+state.chapter);if(!reader||!reader.textContent.includes('Long Noses'))errors.push('Chapter XXIII Arabic passage missing');if(!reader||!reader.textContent.includes('23 من 37'))errors.push('novel progress missing');if(!end||end.textContent.trim()!=='يتبع — لم تكتمل الرواية بعد')errors.push('Arabic incomplete-book label incorrect: '+end?.textContent);if(!primary||primary.textContent.trim()!=='العودة للمكتبة')errors.push('Arabic last-available action incorrect');const navNext=reader?.querySelectorAll('.lt-chapter-nav button')[1];if(reader&&(!navNext||!navNext.disabled))errors.push('future chapter navigation should be disabled');if(reader&&reader.textContent.includes('The End'))errors.push('false ending label present');document.body.setAttribute('data-storylens-qa',errors.length?'FAIL':'PASS');document.body.setAttribute('data-storylens-qa-errors',errors.join(' | '));document.body.setAttribute('data-stl-screenshot','verne23')})();""";
tests["verne23-en"] = r"""(function(){document.documentElement.lang='en';document.documentElement.dir='ltr';const errors=[];try{openStory('around-the-world-in-eighty-days-towle');stlChapter(22)}catch(e){errors.push('navigation: '+e.message)}const reader=document.querySelector('.reader');const end=reader?.querySelector('.chapter-end > div');const primary=reader?.querySelector('.chapter-end > button.primary');if(state.page!=='reader')errors.push('page='+state.page);if(state.chapter!==22)errors.push('chapter='+state.chapter);if(!reader||!reader.textContent.includes('Long Noses'))errors.push('Chapter XXIII English passage missing');if(!reader||!reader.textContent.includes('23 of 37'))errors.push('novel progress missing');if(!end||end.textContent.trim()!=='To be continued — more chapters are coming')errors.push('English incomplete-book label incorrect: '+end?.textContent);if(!primary||primary.textContent.trim()!=='Back to library')errors.push('English last-available action incorrect');const nav=reader?.querySelectorAll('.lt-chapter-nav button');if(!nav||nav.length<2||nav[1].textContent.trim()!=='Next chapter →'||!nav[1].disabled)errors.push('English future-chapter navigation incorrect');document.body.setAttribute('data-storylens-qa',errors.length?'FAIL':'PASS');document.body.setAttribute('data-storylens-qa-errors',errors.join(' | '));document.body.setAttribute('data-stl-screenshot','verne23-en')})();""";
for name,script in tests.items():
 result=source.replace("</body>","<script>\n"+script+"\n</script>\n</body>")
